import numpy as np

def full_sample_z(s):
    """z of every day against the mean and sample sd of the whole series."""
    s = np.asarray(s, dtype=float)
    return (s - s.mean()) / s.std(ddof=1)


def lookahead_days(n, t):
    """The days of an n-day file that a full-sample statistic uses on day t but lie after t."""
    return list(range(t + 1, n))
